"head\">✓</span><span class=\"ink\">      ✓     –</span>\n<span class=\"ink\">frame      </span><span class=\"head\">✓</span><span class=\"ink\">      ✓     –</span>\n<span class=\"ink\">loops      –      –     </span><span class=\"faint\">✓</span></pre>`,\n    timeline: () => `<pre class=\"glyph-field\"><span class=\"faint\">·  2024-11   first frame</span>\n<span class=\"ink\">·  2025-03   graphs land</span>\n<span class=\"head\">●  2026-09   observatory</span>\n<span class=\"faint\">·  next      your page</span></pre>`,\n    stack: () => `<pre class=\"glyph-field\"><span class=\"ink\">docs    </span><span class=\"head\">████████</span><span class=\"mid\">▓▓▓▓</span><span class=\"faint\">░░░░</span>\n<span class=\"ink\">site    </span><span class=\"head\">██████</span><span class=\"mid\">▓▓▓▓▓▓</span><span class=\"faint\">░░</span>\n<span class=\"ink\">pkg     </span><span class=\"head\">████████████</span><span class=\"faint\">░░░░</span></pre>`,\n    slope: () => `<pre class=\"glyph-field\"><span class=\"ink\">latency    240ms  </span><span class=\"head\">→  90ms</span>\n<span class=\"ink\">bundle     84kb   </span><span class=\"head\">→  12kb</span>\n<span class=\"faint\">svg deps     3    →   0</span></pre>`,\n    bullet: () => `<pre class=\"glyph-field\"><span class=\"ink\">CPU  </span><span class=\"head\">[████████████</span><span class=\"faint\">----]</span><span class=\"mid\">|</span><span class=\"ink\"> 72 / 80</span>\n<span class=\"ink\">RAM  </span><span class=\"mid\">[█████</span><span class=\"faint\">---------]</span><span class=\"head\">|</span><span class=\"ink\"> 34 / 64</span>\n<span class=\"ink\">SSD  </span><span class=\"head\">[███████████████]</span><span class=\"mid\">|</span><span class=\"ink\"> 91 / 90</span></pre>`,\n    timer: () => `<div class=\"kpi-block\"><p class=\"n\">04:12:08</p><p class=\"ghost\">elapsed since mount</p></div>`,\n    frame: () => `<p class=\"caption\" style=\"margin-top:4rem\">Dashed edge. [ TITLE ]. Corner marks. This is Graph.</p>`,\n    motif: () => `<pre class=\"glyph-field\"><span class=\"head\">░▒▓█</span> <span class=\"mid\">▓▒░</span> <span class=\"ink\">· = + | ├ └</span>\n<span class=\"faint\">characters, not geometry</span></pre>`,\n    ascii: () => `<pre class=\"glyph-field\"><span class=\"ink\">┌ Client ┐     ┌ Edge ┐</span>\n<span class=\"ink\">│ Svelte │ ──▶ │  V8  │</span>\n<span class=\"ink\">└────┬───┘     └──┬───┘</span>\n<span class=\"faint\">     v            v</span>\n<span class=\"head\">  cache         llm</span></pre>`\n  };\n\n  let fam = \"all\", setIdx = 0, query = \"\", activeSpec = specimens[0];\n  const families = [\"all\",\"graphs\",\"animated\",\"diagrams\",\"frame\"];\n  const famBox = document.getElementById(\"families\");\n  families.forEach((f) => {\n    const b = document.createElement(\"button\");\n    b.className = \"tab\"; b.type = \"button\"; b.textContent = `[ ${f} ]`;\n    b.setAttribute(\"aria-pressed\", f === \"all\" ? \"true\" : \"false\");\n    b.addEventListener(\"click\", () => { fam = f; query = \"\"; document.getElementById(\"find\").value = \"\"; renderIndex(); });\n    famBox.appendChild(b);\n  });\n\n  function visible() {\n    return specimens.filter((s) => (fam === \"all\" || s.fam === fam) && (\n      !query || (s.title + s.name + s.draws).toLowerCase().includes(query)\n    ));\n  }\n  function renderIndex() {\n    const list = visible();\n    [...famBox.children].forEach((b, i) => b.setAttribute(\"aria-pressed\", families[i] === fam ? \"true\" : \"false\"));\n    const box = document.getElementById(\"indexList\");\n    box.innerHTML = \"\";\n    if (!list.length) {\n      box.innerHTML = `<p class=\"ghost\" style=\"padding:0.6rem 0.35rem\">No match.</p>`;\n      return;\n    }\n    if (setIdx >= list.length) setIdx = 0;\n    list.forEach((s, i) => {\n      const btn = document.createElement(\"button\");\n      btn.className = \"spec-btn\"; btn.type = \"button\";\n      btn.setAttribute(\"role\", \"option\");\n      btn.setAttribute(\"aria-selected\", i === setIdx ? \"true\" : \"false\");\n      btn.dataset.odId = \"specimen-\" + s.id;\n      btn.innerHTML = `<span>${s.title.toLowerCase()}</span><span class=\"fam\">${s.fam}</span>`;\n      btn.addEventListener(\"mouseenter\", () => { setIdx = i; showSpecimen(s); });\n      btn.addEventListener(\"click\", () => { setIdx = i; showSpecimen(s); });\n      box.appendChild(btn);\n    });\n    showSpecimen(list[setIdx]);\n  }\n  function showSpecimen(s) {\n    activeSpec = s;\n    document.getElementById(\"setTitle\").textContent = `[ ${s.title} ]`;\n    document.getElementById(\"setMeta\").textContent = `${s.fam} · ${s.name}`;\n    document.getElementById(\"setUsage\").innerHTML = colorize(s.usage);\n    document.getElementById(\"setArt\").innerHTML = (arts[s.art] || arts.motif)();\n    setIdx = visible().indexOf(s);\n    [...document.getElementById(\"indexList\").children].forEach((btn, i) => btn.setAttribute(\"aria-selected\", i === setIdx ? \"true\" : \"false\"));\n  }\n  function openComponent(s) {\n    activeSpec = s;\n    document.getElementById(\"compKicker\").textContent = `[ ${s.fam} · ${s.name} ]`;\n    document.getElementById(\"compTitle\").textContent = s.title.toLowerCase();\n    document.getElementById(\"compLede\").textContent = s.draws.charAt(0).toUpperCase() + s.draws.slice(1) + \".\";\n    document.getElementById(\"compFrameTitle\").textContent = `[ ${s.title} ]`;\n    document.getElementById(\"compArt\").innerHTML = (arts[s.art] || arts.motif)();\n    document.getElementById(\"compPath\").textContent = pathFor(s);\n    document.getElementById(\"compUsage\").innerHTML = colorize(s.usage);\n    document.getElementById(\"copyComp\").dataset.copy = s.usage;\n    const body = document.querySelector(\"#compProps tbody\");\n    body.innerHTML = s.props.map((p) =>\n      `<tr><td>${p.name}</td><td class=\"type\">${p.type}</td><td class=\"note\">${p.note || \"\"}</td></tr>`\n    ).join(\"\");\n    history.replaceState(null, \"\", \"#\" + s.slug);\n    showPage(\"component\", true);\n  }\n\n  document.getElementById(\"find\").addEventListener(\"input\", (e) => { query = e.target.value.trim().toLowerCase(); setIdx = 0; renderIndex(); });\n  document.getElementById(\"openComp\").addEventListener(\"click\", () => openComponent(activeSpec || visible()[setIdx]));\n  document.getElementById(\"copyComp\").addEventListener(\"click\", async () => {\n    await navigator.clipboard.writeText(activeSpec.usage);\n    const b = document.getElementById(\"copyComp\"); b.textContent = \"Copied\"; setTimeout(() => b.textContent = \"Copy\", 1200);\n  });\n\n  const glyphSets = {\n    shade: [\"█\",\"▓\",\"▒\",\"░\"],\n    ascii: [\"#\",\"=\",\"-\", \".\"],\n    hash:  [\"#\",\"+\",\"·\",\" \"],\n    bar:   [\"█\",\"▄\",\"▂\",\" \"]\n  };\n  let glyphId = \"shade\", cornerMark = \"+\", paletteId = \"mono\";\n  function paintRank(set) {\n    const rows = [{ l:\"cpu\", v:12 }, { l:\"ram\", v:6 }, { l:\"ssd\", v:16 }];\n    const g = glyphSets[set];\n    const lines = rows.map((r, i) => {\n      const fill = g[0].repeat(r.v);\n      const empty = g[g.length - 1].repeat(16 - r.v);\n      const cls = i === 0 ? \"head\" : i === 1 ? \"mid\" : \"ink\";\n      return `<span class=\"ink\">${r.l.padEnd(6,\" \")}</span><span class=\"${cls}\">${fill}</span><span class=\"faint\">${empty}</span><span class=\"ink\">  ${[72,34,91][i]}</span>`;\n    });\n    document.getElementById(\"glyphDemo\").innerHTML = lines.join(\"\\n\");\n  }\n  function paintPalette(id) {\n    const a = `<span class=\"head\">████████</span>`;\n    const b = `<span class=\"mid\">▓▓▓▓</span>`;\n    const c = `<span class=\"faint\">░░░░</span>`;\n    const rows = {\n      mono:  [`docs    ${a}${c}${c}`, `site    ${a}${c}${c}`, `pkg     ${a}${c}${c}`],\n      duo:   [`docs    ${a}${b}${c}`, `site    ${a}${b}${c}`, `pkg     ${a}${b}${c}`],\n      multi: [`docs    ${a}${b}<span class=\"hot\">▒▒▒▒</span>`, `site    ${a}${b}<span class=\"hot\">▒▒▒▒</span>`, `pkg     ${a}${b}<span class=\"hot\">▒▒▒▒</span>`]\n    };\n    document.getElementById(\"paletteDemo\").innerHTML = rows[id].map((l) => `<span class=\"ink\">${l}</span>`).join(\"\\n\");\n  }\n  function mkTabs(el, items, get, set, paintFn) {\n    items.forEach((id) => {\n      const b = document.createElement(\"button\");\n      b.className = \"mark-btn\"; b.type = \"button\"; b.textContent = `[ ${id} ]`;\n      b.setAttribute(\"aria-pressed\", get() === id ? \"true\" : \"false\");\n      b.addEventListener(\"click\", () => { set(id); [...el.children].forEach((x) => x.setAttribute(\"aria-pressed\", x === b ? \"true\" : \"false\")); paintFn(id); });\n      el.appendChild(b);\n    });\n  }\n  mkTabs(document.getElementById(\"glyphSet\"), Object.keys(glyphSets), () => glyphId, (v) => glyphId = v, paintRank);\n  mkTabs(document.getElementById(\"paletteSet\"), [\"mono\",\"duo\",\"multi\"], () => paletteId, (v) => paletteId = v, paintPalette);\n  [\"+\",\"*\",\"·\",\"⌜\"].forEach((m) => {\n    const b = document.createElement(\"button\");\n    b.className = \"mark-btn\"; b.type = \"button\"; b.textContent = `[ ${m} ]`;\n    b.setAttribute(\"aria-pressed\", m === \"+\" ? \"true\" : \"false\");\n    b.addEventListener(\"click\", () => {\n      cornerMark = m;\n      [\"cTL\",\"cTR\",\"cBL\",\"cBR\"].forEach((id) => document.getElementById(id).textContent = m);\n      [...document.getElementById(\"cornerSet\").children].forEach((x) => x.setAttribute(\"aria-pressed\", x === b ? \"true\" : \"false\"));\n    });\n    document.getElementById(\"cornerSet\").appendChild(b);\n  });\n  paintRank(\"shade\"); paintPalette(\"mono\");\n\n  const pkgs = { pnpm: \"pnpm add fractalgraphy\", npm: \"npm install fractalgraphy\", bun: \"bun add fractalgraphy\" };\n  let pkg = \"pnpm\";\n  Object.keys(pkgs).forEach((id) => {\n    const b = document.createElement(\"button\");\n    b.className = \"tab\"; b.type = \"button\"; b.textContent = `[ ${id} ]`;\n    b.setAttribute(\"aria-pressed\", id === \"pnpm\" ? \"true\" : \"false\");\n    b.addEventListener(\"click\", () => {\n      pkg = id;\n      document.getElementById(\"pkgCmd\").textContent = pkgs[id];\n      document.getElementById(\"copyPkg\").dataset.copy = pkgs[id];\n      [...document.getElementById(\"pkgSet\").children].forEach((x) => x.setAttribute(\"aria-pressed\", x === b ? \"true\" : \"false\"));\n    });\n    document.getElementById(\"pkgSet\").appendChild(b);\n  });\n  document.getElementById(\"copyPkg\").dataset.copy = pkgs.pnpm;\n  document.getElementById(\"copyPkg\").addEventListener(\"click\", async () => {\n    await navigator.clipboard.writeText(pkgs[pkg]);\n    const b = document.getElementById(\"copyPkg\"); b.textContent = \"Copied\"; setTimeout(() => b.textContent = \"Copy\", 1200);\n  });\n\n  function showPage(id, skipHash) {\n    const isComp = id === \"component\";\n    if (!ROOMS.includes(id) && !isComp) id = \"stage\";\n    document.querySelectorAll(\".view\").forEach((v) => { v.hidden = v.dataset.page !== id; });\n    document.querySelectorAll(\".nav a\").forEach((a) => {\n      const navId = a.dataset.page;\n      const on = navId === id || (isComp && navId === \"set\");\n      a.setAttribute(\"aria-current\", on ? \"page\" : \"false\");\n    });\n    document.querySelector(\".install-chip\").style.visibility = id === \"install\" ? \"hidden\" : \"visible\";\n    try { localStorage.setItem(PAGE_KEY, isComp ? activeSpec.slug : id); } catch {}\n    if (id !== \"stage\" && timer) { clearInterval(timer); timer = 0; }\n    if (id === \"stage\") mount(current);\n    if (id === \"set\") renderIndex();\n    if (!skipHash && !isComp) history.replaceState(null, \"\", \"#\" + id);\n  }\n\n  function route(hash) {\n    const h = (hash || \"\").replace(\"#\", \"\");\n    if (!h || ROOMS.includes(h)) { showPage(h || \"stage\"); return; }\n    const s = specimens.find((x) => x.slug === h || x.id === h);\n    if (s) openComponent(s);\n    else showPage(\"stage\");\n  }\n\n  document.querySelectorAll(\"[data-go], .nav a, .brand-mark\").forEach((a) => {\n    a.addEventListener(\"click\", (e) => {\n      const href = a.getAttribute(\"href\") || a.dataset.go;\n      if (!href || href.startsWith(\"http\")) return;\n      const id = (a.dataset.go || href.replace(\"#\", \"\") || \"stage\");\n      if (!ROOMS.includes(id) && id !== \"component\") return;\n      e.preventDefault();\n      showPage(id);\n    });\n  });\n  document.querySelectorAll(\"[data-open]\").forEach((btn) => {\n    btn.addEventListener(\"click\", () => {\n      const s = specimens.find((x) => x.id === btn.dataset.open);\n      if (s) openComponent(s);\n    });\n  });\n  window.addEventListener(\"hashchange\", () => route(location.hash));\n\n  document.addEventListener(\"keydown\", (e) => {\n    const page = document.querySelector(\".view:not([hidden])\")?.dataset.page;\n    if (page === \"stage\" && (e.key === \"j\" || e.key === \"ArrowRight\")) { e.preventDefault(); mount(current + 1); }\n    if (page === \"stage\" && (e.key === \"k\" || e.key === \"ArrowLeft\")) { e.preventDefault(); mount(current - 1); }\n    if (page === \"set\" && (e.key === \"j\" || e.key === \"ArrowDown\")) {\n      e.preventDefault(); const list = visible(); setIdx = (setIdx + 1) % list.length; showSpecimen(list[setIdx]); renderIndex();\n    }\n    if (page === \"set\" && (e.key === \"k\" || e.key === \"ArrowUp\")) {\n      e.preventDefault(); const list = visible(); setIdx = (setIdx - 1 + list.length) % list.length; showSpecimen(list[setIdx]); renderIndex();\n    }\n  });\n\n  document.getElementById(\"copyUsage\").addEventListener(\"click\", () => {\n    navigator.clipboard.writeText(instruments[current].usage);\n    const b = document.getElementById(\"copyUsage\"); b.textContent = \"Copied\"; setTimeout(() => b.textContent = \"Copy code\", 1200);\n  });\n  document.querySelectorAll(\"[data-copy]\").forEach((btn) => {\n    btn.addEventListener(\"click\", async () => {\n      await navigator.clipboard.writeText(btn.dataset.copy);\n      const prev = btn.textContent; btn.textContent = \"Copied\"; setTimeout(() => (btn.textContent = prev), 1200);\n    });\n  });\n  document.querySelectorAll(\".accent-dot\").forEach((btn) => {\n    btn.addEventListener(\"click\", () => {\n      document.documentElement.style.setProperty(\"--accent\", btn.dataset.accent);\n      document.documentElement.style.setProperty(\"--accent-2\", btn.dataset.accent2);\n      document.querySelectorAll(\".accent-dot\").forEach((b) => b.setAttribute(\"aria-pressed\", b === btn ? \"true\" : \"false\"));\n    });\n  });\n\n  const spark = \"▁▃▄▅▆▅▇▆█▇█\";\n  const sparkEl = document.getElementById(\"spark\");\n  if (sparkEl) sparkEl.textContent = spark + spark;\n  const draft = [40, 62, 70, 86, 48];\n  const shipped = [70, 86, 78, 96, 88];\n  const mkBars = (el, vals) => { if (el) el.innerHTML = vals.map((v) => `<i style=\"height:${v}%\"></i>`).join(\"\"); };\n  mkBars(document.getElementById(\"barsDraft\"), draft);\n  mkBars(document.getElementById(\"barsShipped\"), shipped);\n  const heat = document.getElementById(\"heat\");\n  if (heat) {\n    const hr = mulberry32(21);\n    for (let i = 0; i < 53 * 7; i++) {\n      const n = hr();\n      const v = n > 0.86 ? 1 : n > 0.7 ? 0.72 : n > 0.5 ? 0.45 : n > 0.28 ? 0.22 : 0.08;\n      const cell = document.createElement(\"b\");\n      cell.style.setProperty(\"--cell\", `color-mix(in oklab, var(--accent) ${Math.round(v * 100)}%, #000000)`);\n      heat.appendChild(cell);\n    }\n  }\n\n  const start = (location.hash || \"\").replace(\"#\",\"\") || (localStorage.getItem(PAGE_KEY) || \"stage\");\n  route(\"#\" + start);\n  if (!document.querySelector(\".view:not([hidden])\")) showPage(\"stage\");\n  mount(0);\n})();\n</script>\n</body>\n</html>\n";
